MMRPG_COMPENDIUM.getLocalizedPower = function(p, lang) {
    if (!p) return null;
    let base = (typeof p === 'string')
        ? MMRPG_COMPENDIUM.POWERS.find(item => item.name.toLowerCase() === p.toLowerCase())
        : p;
    if (!base) return (typeof p === 'string' ? { name: p, effect: '' } : p);

    lang = lang || (typeof MMRPG_I18N !== 'undefined' ? MMRPG_I18N.currentLang : 'de') || 'de';
    const cleanSet = MMRPG_COMPENDIUM.getCleanSetName(base.set);

    let effect = base.effect || '';
    if (lang !== 'de' && MMRPG_COMPENDIUM.LOCALIZATIONS[lang] && MMRPG_COMPENDIUM.LOCALIZATIONS[lang].powers && MMRPG_COMPENDIUM.LOCALIZATIONS[lang].powers[base.name]) {
        effect = MMRPG_COMPENDIUM.LOCALIZATIONS[lang].powers[base.name];
    }

    return {
        ...base,
        set: cleanSet,
        action: MMRPG_COMPENDIUM.getLocalizedAction(base.action, lang),
        range: MMRPG_COMPENDIUM.getLocalizedRange(base.range, lang),
        duration: MMRPG_COMPENDIUM.getLocalizedDuration(base.duration, lang),
        effect: effect
    };
};

MMRPG_COMPENDIUM.getLocalizedTrait = function(t, lang) {
    if (!t) return null;
    let base = (typeof t === 'string')
        ? MMRPG_COMPENDIUM.TRAITS.find(item => item.name.toLowerCase() === t.toLowerCase())
        : t;
    if (!base) return (typeof t === 'string' ? { name: t, description: '' } : t);

    lang = lang || (typeof MMRPG_I18N !== 'undefined' ? MMRPG_I18N.currentLang : 'de') || 'de';
    let desc = base.description || '';
    if (lang !== 'de' && MMRPG_COMPENDIUM.LOCALIZATIONS[lang] && MMRPG_COMPENDIUM.LOCALIZATIONS[lang].traits && MMRPG_COMPENDIUM.LOCALIZATIONS[lang].traits[base.name]) {
        desc = MMRPG_COMPENDIUM.LOCALIZATIONS[lang].traits[base.name];
    }

    return {
        ...base,
        description: desc
    };
};

if (typeof module !== 'undefined' && module.exports) {
    module.exports = MMRPG_COMPENDIUM;
}
